// === Tab: mySketch ===
//Code by Aaron Reuland
//Palette inspired by paintings from Picasso's Blue Period.

let blues=['#470078','#B28DC6','#5500AC','#6A02A1','#5200AD','#9F43B6','#16002E', '#4C0078']
let drops=[]
let colorSpeed

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(random(blues));
	noStroke()
}

function draw(){
	clear()
	colorSpeed= frameCount/150
if(frameCount%5==0){
	 let y= noise(frameCount/8)*height
	 let x= noise(frameCount/5+1)*width
	drops.push(new drop(x, y))
}
blendMode(BLEND)
	for(let y=0; y<=height+4; y+=4){
		fill(colorMixer(y, blues, 0, 255))
		rect(0, y, width, 4)
	} 
	blendMode(BURN)
	for(let xoff= 0; xoff<width/3; xoff+=4){
		let a= map(xoff, 0, width/3, 255, 1)
		fill(colorMixer(xoff, blues, 0.3, a))
		rect(xoff, 0, 4, height)
		rect(width-xoff, 0, 4, height)

	}

	for(let i=drops.length-1; i>=0; i--){
		drops[i].draw();
		drops[i].die();
	}

}



function colorMixer(y, colorArray, off, alpha) {
	let c = noise(y/400, colorSpeed+off) * colorArray.length
	let c1 = floor(c)
	let c2 = floor(c + 1) % colorArray.length
	let color1 = colorArray[c1]
	let color2 = colorArray[c2]
	let mix = fract(c)
	let coloring = color(spectral.mix(color1, color2, mix))
	coloring.setAlpha(alpha)
	return coloring
}


class drop{
	constructor(x, y, c){
		this.pos=createVector(x, y)
		this.life=random(10, 80)
		this.drip=1
		this.alpha=0
		this.color=c
	}

	draw(){
		push()
		blendMode(SOFT_LIGHT)
		strokeWeight(1)
		let cAlpha= map(abs(this.life/2-this.drip), 0, this.life/2, 255, 0)
	noFill()
	for(let r=1; r<=this.drip; r++){
		let stroker=colorMixer(this.pos.y, blues, r/100, cAlpha)
		stroke(stroker)
		ellipse(this.pos.x, this.pos.y, r)
	}

	pop()	
	}

	die(){
		this.drip+=0.5
		this.pos.y+=0.5
		if(this.drip>=this.life){
			let index= drops.indexOf(this)
			drops.splice(index, 1)
		}

	}

}

